  const pw=[T('Authority (legitimate)','Authority (legitimate)'),T('Control over resources','Control over resources'),T('Reward','Reward'),T('Coercion','Force'),T('Charisma','Charisma'),T('Expressiveness (political skill)','Expressiveness (political skill)')];
  const pG=pw.map((x,i)=>{const a=-Math.PI/2+i/6*Math.PI*2,cx=300+Math.cos(a)*170,cy=220+Math.sin(a)*130;const g=el('g',{},Bg);el('line',{x1:300,y1:220,x2:cx,y2:cy,stroke:'var(--line)','stroke-width':2},g);node(g,cx,cy,x,'var(--org-soft)',170,32);return g;});el('circle',{cx:300,cy:220,r:34,fill:'var(--org)'},Bg);t_(Bg,300,225,T('Leader','Leader'),{'text-anchor':'middle','font-size':13,'font-weight':700,fill:'var(--paper)'});
  t_(Bg,300,410,T('Three dominant theories: trait, attitudinal, contingency','Three main theory: trait, attitudinal, contingency'),{'text-anchor':'middle','font-size':12,fill:'var(--muted)'});
  // 2: culture vs climate
  const C=tab(s);tabs.push([C,2,3]);title(C,32,'Culture is the personality; climate is the mood','Culture na di character; climate na di mood');
  box(C,30,60,260,300,'var(--org-soft)','none',14);box(C,310,60,260,300,'var(--data-soft)','none',14);
