function u23Sandbox(ctl,st){
  const sits=[['emerg',T('An emergency or crisis','Emergency or crisis')],['dir',T('The team needs a new direction','Team need new direction')],['heal',T('Trust is broken; team needs healing','Trust don spoil; team need healing')],['ideas',T('You need fresh ideas and buy-in','You need new idea and make everybody agree')],['experts',T('Highly skilled, self-driven team; tight deadline','Team wey sabi work and dey push demself; deadline tight')],['grow',T('Staff want to develop long-term','Staff wan grow for long time')]];
  let sit='emerg',sty='coe';const ro=H.readout(ctl);const s=H.svg(st,520,240);
  H.segBtns(ctl,T('Situation','Situation'),sits,'emerg',v=>{sit=v;draw();});
  H.segBtns(ctl,T('Your style','Your style'),STY.map(x=>[x.key,Course.L(x.n).split(' (')[0]]),'coe',v=>{sty=v;draw();});
  function draw(){s.innerHTML='';const S=STY.find(x=>x.key===sty);const fit=S.when===sit;const near={dir:['coa','dem'],heal:['coa','dem'],ideas:['aff','coa'],grow:['aut','aff'],emerg:['aut'],experts:['aut']}[sit]||[];
    const score=fit?92:near.includes(sty)?62:sty==='coe'||sty==='pac'?18:40;
    el('rect',{x:30,y:60,width:460,height:30,rx:15,fill:'var(--sunk)'},s);el('rect',{x:30,y:60,width:4.6*score,height:30,rx:15,fill:score>70?'var(--org)':score>45?'var(--data)':'var(--err)'},s);t_(s,30,46,T('Fit with the situation','How e fit di situation'),{'font-size':13,'font-weight':700});
    t_(s,30,130,T('Climate effect: ','Effect on climate: ')+(S.cl>0?'+'.repeat(S.cl):'−'.repeat(-S.cl)),{'font-size':15,'font-weight':700,fill:S.cl>0?'var(--org)':'var(--err)'});
    wrap(s,30,170,'✓ '+Course.L(S.pos),70,{'font-size':12});wrap(s,30,210,'✗ '+Course.L(S.neg),70,{'font-size':12});
    ro.innerHTML=(fit?T('<b>Good match.</b> ','<b>E match well.</b> '):near.includes(sty)?T('<b>Can work.</b> ','<b>E fit work.</b> '):T('<b>Risky here.</b> ','<b>E get risk here.</b> '))+T('Every style is useful at the right time and disastrous at the wrong one. Leaders who master four or more (especially authoritative, democratic, affiliative and coaching) get the best climate and results.','Every style get time wey e good and time wey e go cause disaster. Leaders wey sabi four or more (mostly authoritative, democratic, affiliative and coaching) dey get di best climate and result.');}
  draw();H.tag(st,T('Illustrative scoring based on the course’s pros and cons','Example scoring from di good and bad wey di course list'));
}
Course.add({id:'2.3',module:2,title:B('Leadership and Organisational Climate','Leadership and Organisational Climate'),vizLabel:B('Six leadership styles moving five climate gauges','Six leadership style wey dey move five climate gauge'),
  hook:{who:B('Mr Adewale, new branch manager','Mr Adewale, new branch manager'),text:B('Under the last manager, staff whispered and kept their heads down. Mr Adewale has the same staff, same pay, same building. Within three months the branch feels different. What changed is the climate, and he set it.','For di last manager time, staff dey whisper and dey keep quiet. Mr Adewale get di same staff, di same salary, di same building. Before three months, di branch dey feel different. Wetin change na di climate, and na im set am.')},
  objectives:[B('Discuss leadership: meaning, power and theories','Discuss leadership: meaning, power and theory'),B('Explain organisational climate','Explain organisational climate'),B('Distinguish organisational culture from climate','Show di difference between organisational culture and climate'),B('Discuss how six leadership styles affect climate','Discuss how six leadership style dey affect climate')],
  steps:[
    {h:B('What leadership is','Wetin leadership be'),t:B('<p>Hersey and Blanchard: the successful organisation’s one distinguishing attribute is dynamic, effective leadership. Leadership is the <b>power to influence others</b> to do what they otherwise would not, towards a goal, in a given situation. It depends on the leader, the followers and the situation, and balances <b>task</b> and <b>people</b>. Agbonifoh et al. add: as painlessly as possible, with commitment, integrity, honesty, accountability and freedom of dissent.</p>','<p>Hersey and Blanchard: di one thing wey dey separate successful organisation na leadership wey get life and wey dey work. Leadership na <b>power to influence people</b> make dem do wetin dem no for do by demself, toward goal, for one situation. E depend on di leader, followers and situation, and e dey balance <b>work</b> and <b>people</b>. Agbonifoh and others add: make e no pain people, with commitment, integrity, honesty, accountability and freedom to disagree.</p>')},
    {h:B('Sources of power','Where power dey come from'),t:B('<p>A leader’s power comes from <b>authority</b> (legitimate power), <b>control over resources</b>, <b>reward</b>, <b>coercion</b>, <b>charisma</b> and <b>expressiveness</b> (political skill to widen influence). Three dominant theories: <b>trait</b>, <b>attitudinal</b> and <b>contingency</b>.</p>','<p>Leader power dey come from <b>authority</b> (legitimate power), <b>control over resources</b>, <b>reward</b>, <b>force</b>, <b>charisma</b> and <b>expressiveness</b> (political skill to spread influence). Three main theory: <b>trait</b>, <b>attitudinal</b> and <b>contingency</b>.</p>')},
    {h:B('Culture vs climate','Culture vs climate'),t:B('<p><b>Culture</b> is the shared assumptions, values and beliefs that govern behaviour: the organisation’s <b>personality</b>, deeply ingrained and hard to change. <b>Climate</b> is how members experience that culture: the organisation’s <b>mood</b>. It changes often, is easier to measure and change, and top management can shape it.</p>','<p><b>Culture</b> na di assumption, value and belief wey everybody share, wey dey control how people behave: di organisation <b>character</b>, e don enter dia blood and e hard to change. <b>Climate</b> na how members dey feel di culture: di organisation <b>mood</b>. E dey change often, e easy to measure and change, and top management fit shape am.</p>'),say:B('Culture is who your friend is; climate is what mood they are in today.','Culture na who your friend be; climate na di mood wey e dey today.')},
    {h:B('Types of climate','Types of climate'),t:B('<p>Halpin and Croft (1963) name six: <b>open, autonomous, controlled, familiar, paternal, closed</b>. Climates can also be grouped as <b>people-, rule-, innovation- or goal-oriented</b>. Climate is driven by flexibility, standards, accurate feedback and rewards, clarity of mission and values, and commitment to a common purpose.</p>','<p>Halpin and Croft (1963) name six: <b>open, autonomous, controlled, familiar, paternal, closed</b>. You fit still group climate as <b>people-, rule-, innovation- or goal-oriented</b>. Wetin dey drive climate: flexibility, standard, correct feedback and reward, clear mission and value, and commitment to common purpose.</p>')},
    {h:B('Coercive and authoritative','Coercive and authoritative'),t:B('<p><b>Coercive</b> (the dictator): fine in emergencies or to shock people out of failed habits, but top-down orders kill initiative and motivation. <b>Authoritative</b> (the visionary): the most effective of the six, giving clear direction and freedom to innovate, but it fails with more experienced experts and can turn overbearing.</p>','<p><b>Coercive</b> (dictator): e good for emergency or to shake people comot from bad habit, but order from top dey kill initiative and motivation. <b>Authoritative</b> (visionary): di most effective for di six, e dey give clear direction and freedom to try new thing, but e no dey work with expert wey sabi pass and e fit become too much.</p>')},
    {h:B('Affiliative and democratic','Affiliative and democratic'),t:B('<p><b>Affiliative</b> (the people’s person): builds loyalty and belonging with lots of praise, but poor performance can go uncorrected. <b>Democratic</b> (the listener): gives staff a say, raising flexibility and responsibility, but staff may not be informed enough, and consensus may never come.</p>','<p><b>Affiliative</b> (people person): e dey build loyalty and belonging with plenty praise, but dem fit no correct bad performance. <b>Democratic</b> (listener): e dey give staff voice, e increase flexibility and responsibility, but staff fit no sabi reach, and agreement fit no come.</p>')},
    {h:B('Pacesetting and coaching','Pacesetting and coaching'),t:B('<p><b>Pacesetting</b> (superman or superwoman): fast with highly competent, self-motivated staff, but morale drops when demands overwhelm people. <b>Coaching</b> (the nurturer): builds strengths and long-term goals, but fails if staff resist learning. Leaders who use climate-friendly styles get better financial results; those who master four or more styles get the best climate.</p>','<p><b>Pacesetting</b> (superman or superwoman): e fast with staff wey sabi work and dey push demself, but morale go fall when demand too much. <b>Coaching</b> (nurturer): e dey build strength and long-term goal, but e no go work if staff no wan learn. Leaders wey dey use style wey good for climate dey get better money result; di ones wey sabi four or more style dey get di best climate.</p>')}
  ],
  scene:u23Scene,
  words:[[B('Leadership','Leadership'),B('Influencing people to work willingly towards a goal.','To influence people make dem work with dia mind toward goal.')],[B('Organisational culture','Organisational culture'),B('Shared values and beliefs: the firm’s personality.','Value and belief wey dem share: di company character.')],[B('Organisational climate','Organisational climate'),B('How it feels to work there right now: the firm’s mood.','How e dey feel to work there now: di company mood.')],[B('Coercive power','Coercive power'),B('Power based on threats or punishment.','Power wey base on threat or punishment.')],[B('Charisma','Charisma'),B('Personal attraction that makes people want to follow.','Personal attraction wey dey make people wan follow you.')]],
  sandboxIntro:B('Pick a situation and a leadership style to see whether they fit, and what the style does to the climate.','Pick situation and leadership style make you see whether dem fit, and wetin di style go do to di climate.'),
  sandbox:u23Sandbox,
  sae:{q:B('What is organisational climate? Distinguish organisational culture from climate, and explain the relationship between them.','Wetin be organisational climate? Show di difference between culture and climate, and explain how dem relate.'),a:B('Climate is the set of perceptions staff share about the workplace’s policies and practices, and what gets rewarded. Culture is the system of shared assumptions, values and beliefs. Culture is the personality (deep, slow to change); climate is how members experience that culture, the mood (frequent changes, easier to measure, shaped by top management). Culture produces the atmosphere that people feel as climate.','Climate na di way staff dey see policy, practice, and wetin dey get reward for di workplace. Culture na di assumption, value and belief wey everybody share. Culture na di character (e deep, e slow to change); climate na how members dey feel di culture, di mood (e dey change often, e easy to measure, top management fit shape am). Culture dey create di atmosphere wey people dey feel as climate.')},
  tma:{q:B('Assess the impact of leadership on organisational climate in a manufacturing firm.','Assess di impact of leadership on organisational climate for manufacturing company.'),outline:[B('Define leadership and climate','Explain leadership and climate'),B('The five climate drivers (flexibility, standards, rewards, clarity, commitment)','Di five climate drivers (flexibility, standard, reward, clarity, commitment)'),B('Apply each of the six styles to factory situations (e.g. a safety emergency, a new product line)','Apply each of di six style to factory situation (like safety emergency, new product line)'),B('Evidence: climate-friendly styles → better results; mastering 4+ styles','Evidence: style wey good for climate → better result; to sabi 4+ style'),B('Recommend a style mix for the firm','Recommend mix of style for di company')]},
  quiz:[
    {q:B('Which style does the course call the most effective of the six?','Which style di course call di most effective for di six?'),o:[B('Coercive','Coercive'),B('Authoritative','Authoritative'),B('Pacesetting','Pacesetting'),B('Democratic','Democratic')],a:1,w:B('It gives clear direction and freedom to innovate.','E dey give clear direction and freedom to try new thing.')},
    {q:B('If culture is the organisation’s personality, climate is its…','If culture na di organisation character, climate na im…'),o:[B('Budget','Budget'),B('Mood','Mood'),B('Chart','Chart'),B('Logo','Logo')],a:1,w:B('Climate changes more often and is easier to measure.','Climate dey change often and e easy to measure.')},
    {q:B('The coercive style is appropriate…','Coercive style good…'),o:[B('With expert peers','With expert wey sabi pass'),B('In severe situations and emergencies','For serious situation and emergency'),B('For long-term development','For long-term growth'),B('Never','Never')],a:1,w:B('It can also break failed business habits.','E fit still break bad business habit.')},
    {q:B('Halpin and Croft’s six climates include…','Halpin and Croft six climate include…'),o:[B('Open and closed','Open and closed'),B('Hot and cold','Hot and cold'),B('Tall and flat','Tall and flat'),B('Line and staff','Line and staff')],a:0,w:B('Open, autonomous, controlled, familiar, paternal, closed.','Open, autonomous, controlled, familiar, paternal, closed.')}
  ],
  card:[{h:B('Sources of leader power','Where leader power dey come from'),items:[B('Authority','Authority'),B('Control over resources','Control over resources'),B('Reward power','Reward power'),B('Coercive power','Coercive power'),B('Charisma','Charisma'),B('Expressiveness','Expressiveness')]},{h:B('Six leadership styles','Six leadership style'),items:STY.map(x=>x.n)},{h:B('Halpin & Croft climates','Halpin & Croft climate'),items:[B('Open','Open'),B('Autonomous','Autonomous'),B('Controlled','Controlled'),B('Familiar','Familiar'),B('Paternal','Paternal'),B('Closed','Closed')]},{h:B('Climate drivers','Wetin dey drive climate'),items:[B('Flexibility','Flexibility'),B('Standards','Standard'),B('Accurate feedback and rewards','Correct feedback and reward'),B('Clarity of mission and values','Clear mission and value'),B('Commitment to a common purpose','Commitment to common purpose')]}]
});

