  const rq=[T('How did people respond to past changes?','How people take react to change before?'),T('What other big changes are happening now?','Which other big change dey happen now?'),T('Is top management visibly supporting it?','Top management dey show say dem support am?')];
  const rG=rq.map((x,i)=>{const g=el('g',{},Bg);box(g,60,64+i*72,480,56,'var(--sunk)','none',12);t_(g,82,98+i*72,x,{'font-size':13.5});return g;});
