  const rgG=rings.map(([r,c,l],i)=>{const g=el('g',{},C);el('circle',{cx:300,cy:225,r,fill:c},g);return g;});
  t_(C,300,230,T('Sponsor','Sponsor'),{'text-anchor':'middle','font-size':12.5,'font-weight':700,fill:'var(--paper)'});t_(C,300,135,T('Stakeholders','Stakeholders'),{'text-anchor':'middle','font-size':12,'font-weight':700});t_(C,300,78,T('Everyone else','Everybody else'),{'text-anchor':'middle','font-size':12,'font-weight':700});
  wrap(C,300,415,T('Sponsor checklist: good at influencing peers, and brave enough to engage opponents.','Sponsor checklist: e sabi influence im mate, and e get mind to face people wey no support.'),76,{'text-anchor':'middle','font-size':11.5});
  // 3: say yes vs do
  const D=tab(s);tabs.push([D,3,4]);title(D,32,'Saying “yes” is not the same as doing it','To talk “yes” no be di same as to do am');
  const yes=el('rect',{x:120,y:120,width:120,rx:8,fill:'var(--org)'},D),doi=el('rect',{x:360,y:120,width:120,rx:8,fill:'var(--data)'},D);
  t_(D,180,330,T('openly supportive','dem talk say dem support'),{'text-anchor':'middle','font-size':12.5,'font-weight':700});t_(D,420,330,T('actually applying it','dem dey do am for real'),{'text-anchor':'middle','font-size':12.5,'font-weight':700});
  wrap(D,300,370,T('Find out what each person needs (skills, adjustments) to leap from “yes” to doing. Explain why the status quo is failing, then paint the future, again and again.','Find out wetin each person need (skill, adjustment) to jump from “yes” go action. Explain why di old way no dey work, then paint di future, again and again.'),74,{'text-anchor':'middle','font-size':12});
  t_(D,560,100,T('Illustrative','Example'),{'font-size':10,'text-anchor':'end',fill:'var(--muted)'});
  // 4: training reduces stress
  const E=tab(s);tabs.push([E,4,5]);title(E,32,'Key 3: train early, before start-up','Key 3: train dem early, before di new thing start');
  const ax=H.axes(E,{x:70,y:70,w:460,h:230,xmin:0,xmax:10,ymin:0,ymax:10,xt:[[2,T('training','training')],[5,T('start-up','start-up')],[9,T('later','later')]],yt:[],yl:T('stress and resistance','stress and resistance'),xl:T('time','time')});
  const late=el('path',{fill:'none',stroke:'var(--err)','stroke-width':3},E),early=el('path',{fill:'none',stroke:'var(--org)','stroke-width':3},E);el('line',{x1:ax.sx(5),x2:ax.sx(5),y1:ax.sy(10),y2:ax.sy(0),stroke:'var(--muted)','stroke-dasharray':'4 4'},E);
  t_(E,530,90,T('— trained late','— dem train dem late'),{'font-size':12,fill:'var(--err)','font-weight':700,'text-anchor':'end'});t_(E,530,110,T('— trained early','— dem train dem early'),{'font-size':12,fill:'var(--org)','font-weight':700,'text-anchor':'end'});
  wrap(E,300,355,T('Managers also need skills: team building, coaching, feedback, priorities, negotiating, stress management, conflict, problem-solving and delegation.','Managers still need skill: team building, coaching, feedback, priority, negotiation, stress management, conflict, problem-solving and delegation.'),74,{'text-anchor':'middle','font-size':12});
  t_(E,560,412,T('Illustrative curves','Example curve'),{'font-size':10,'text-anchor':'end',fill:'var(--muted)'});
  // 5: impact 5 steps
